"""Probe: Hebrew business profile of one company from its 10-K, generated by Gemini.

The API key is read from GOOGLE_API_KEY in .env and sent only in the request header to
Google's API; it is never printed.

Usage:
  uv run python probes/gemini/business_summary.py --list-models
  uv run python probes/gemini/business_summary.py --model MODEL --url 10K_URL --company NAME
"""

from __future__ import annotations

import argparse
import json
import os
import sys
import time
from pathlib import Path

import httpx
from dotenv import load_dotenv

API = "https://generativelanguage.googleapis.com/v1beta"

PROMPT = """אתה אנליסט השקעות ערך. קרא את דוח ה-10-K של {company} בכתובת הבאה, ובעיקר את
Item 1 (Business), Item 7 (MD&A) והביאורים על המגזרים (segment information):
{url}

כתוב בעברית פרופיל עסקי מעמיק של החברה, למשקיע שלא מכיר אותה. הכללים:
- הסתמך רק על מה שכתוב בדוח. אל תוסיף ידע חיצוני ואל תנחש.
- מספרים (הכנסות, אחוזים, מספר עובדים וכו') רק אם הם מופיעים בדוח, עם שנת הכספים.
- מונחים מקצועיים ושמות מוצרים שאין להם תרגום טוב בעברית — השאר באנגלית
  (למשל HVAC, backlog, OEM, recurring revenue). שמות מגזרים ומותגים — באנגלית.
- היה ספציפי: שמות מוצרים, סוגי לקוחות, שווקים. בלי משפטים כלליים כמו "חברה מובילה".

מבנה התשובה (Markdown, בדיוק הכותרות האלה):
## במשפט אחד
## מה החברה מוכרת
(לכל מגזר: מה הוא מוכר, דוגמאות למוצרים/שירותים, ואחוז מההכנסות אם מופיע)
## מי הלקוחות ואיך החברה מגיעה אליהם
(סוגי לקוחות, ערוצי הפצה, פיזור גיאוגרפי, תלות בלקוח גדול אם יש)
## איך החברה מרוויחה כסף
(מודל עסקי: מכירה חד-פעמית/חוזרת, שירות, חוזים; מה מניע את הרווחיות)
## תחרות ויתרון תחרותי
(מתחרים שהחברה מזכירה, ובמה היא טוענת שהיא שונה)
## רגישויות ותלויות
(מחזוריות, עונתיות, חומרי גלם, רגולציה, ריכוזיות ספקים/לקוחות)
## מה קרה בשנה האחרונה
(לפי ה-MD&A: מה הניע את ההכנסות והרווחיות, רכישות, שינויים מהותיים)
"""


def client() -> httpx.Client:
    load_dotenv()
    key = os.environ.get("GOOGLE_API_KEY")
    if not key:
        sys.exit("GOOGLE_API_KEY is not set")
    return httpx.Client(headers={"x-goog-api-key": key}, timeout=300)


def list_models() -> None:
    with client() as c:
        models = c.get(f"{API}/models", params={"pageSize": 200}).json().get("models", [])
    for m in models:
        if "flash" in m["name"] and "generateContent" in m.get("supportedGenerationMethods", []):
            print(m["name"], "|", m.get("displayName"), "| thinking:", m.get("thinking"))


def summarize(model: str, url: str, company: str, thinking: str, out: Path) -> None:
    prompt = PROMPT.format(company=company, url=url)
    body = {
        "contents": [{"role": "user", "parts": [{"text": prompt}]}],
        "tools": [{"url_context": {}}],
        "generationConfig": {"thinkingConfig": {"thinkingLevel": thinking}},
    }
    t0 = time.time()
    with client() as c:
        resp = c.post(f"{API}/models/{model}:generateContent", json=body)
    print("status", resp.status_code, f"{time.time() - t0:.0f}s")
    data = resp.json()
    if resp.status_code != 200:
        print(json.dumps(data, ensure_ascii=False)[:1500])
        return
    cand = data["candidates"][0]
    text = "".join(p.get("text", "") for p in cand["content"]["parts"])
    meta = cand.get("urlContextMetadata") or cand.get("url_context_metadata")
    print("url context:", json.dumps(meta, ensure_ascii=False)[:500])
    print("usage:", data.get("usageMetadata"))
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(text, encoding="utf-8")
    print("saved to", out)


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--list-models", action="store_true")
    ap.add_argument("--ping", action="store_true")
    ap.add_argument("--model")
    ap.add_argument("--url")
    ap.add_argument("--company")
    ap.add_argument("--thinking", default="medium")
    ap.add_argument("--out", default="var/probe-gemini/summary.md")
    a = ap.parse_args()
    if a.list_models:
        list_models()
    elif a.ping:
        with client() as c:
            r = c.post(f"{API}/models/{a.model}:generateContent",
                       json={"contents": [{"parts": [{"text": "Reply with the word OK."}]}]})
        print(a.model, r.status_code, r.text[:200])
    else:
        summarize(a.model, a.url, a.company, a.thinking, Path(a.out))


if __name__ == "__main__":
    main()
